import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from normalizedStackedArea ----
/**
 * US electricity net generation by source, 2001-2023 (EIA), in terawatt-hours.
 * Six sources that together cover the great majority of the grid, so the
 * expanded shares read as an honest picture of the mix rather than a residual.
 */
const SOURCES = [
  'Coal',
  'Natural gas',
  'Nuclear',
  'Hydro',
  'Wind',
  'Solar'
] as const;

type Source = (typeof SOURCES)[number];

type GenerationRow = { date: Date } & Record<Source, number>;

const YEARS: [string, ...number[]][] = [
  ['2001-01-01', 1904, 639, 769, 217, 7, 0.5],
  ['2002-01-01', 1933, 691, 780, 264, 10, 0.6],
  ['2003-01-01', 1974, 650, 764, 276, 11, 0.5],
  ['2004-01-01', 1978, 710, 789, 268, 14, 0.6],
  ['2005-01-01', 2013, 761, 782, 270, 18, 0.6],
  ['2006-01-01', 1991, 816, 787, 289, 26, 0.5],
  ['2007-01-01', 2016, 897, 806, 248, 34, 0.6],
  ['2008-01-01', 1986, 883, 806, 254, 55, 0.9],
  ['2009-01-01', 1756, 921, 799, 273, 74, 0.9],
  ['2010-01-01', 1847, 988, 807, 260, 95, 1.2],
  ['2011-01-01', 1733, 1013, 790, 319, 120, 1.8],
  ['2012-01-01', 1514, 1225, 769, 276, 141, 4.3],
  ['2013-01-01', 1581, 1124, 789, 269, 168, 9.0],
  ['2014-01-01', 1582, 1126, 797, 259, 182, 17.7],
  ['2015-01-01', 1352, 1333, 797, 250, 191, 24.9],
  ['2016-01-01', 1239, 1380, 806, 267, 227, 36.8],
  ['2017-01-01', 1206, 1296, 805, 300, 254, 53.3],
  ['2018-01-01', 1146, 1468, 807, 292, 275, 63.8],
  ['2019-01-01', 966, 1586, 809, 288, 295, 71.9],
  ['2020-01-01', 774, 1624, 790, 291, 338, 90.9],
  ['2021-01-01', 899, 1579, 778, 260, 380, 115],
  ['2022-01-01', 828, 1689, 772, 254, 434, 146],
  ['2023-01-01', 675, 1802, 775, 240, 425, 178]
];

const generationBySource: GenerationRow[] = YEARS.map(([date, ...values]) => {
  const row = { date: new Date(date) } as GenerationRow;
  SOURCES.forEach((source, i) => {
    row[source] = values[i] ?? 0;
  });
  return row;
});

const MARGIN = { top: 56, right: 16, bottom: 36, left: 52 };
const LEGEND_COLUMNS = 3;

/** One row per period holding every source's value, plus the sources to stack bottom to top. */
export type Data = { rows: GenerationRow[]; sources: readonly Source[] };

const DEMO: Data = { rows: generationBySource, sources: SOURCES };

export default function NormalizedStackedAreaChart({
  data = DEMO,
  width
}: {
  data?: Data;
  width: number;
}) {
  const height = Math.round(width * 0.58);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;

  // stackOffsetExpand rescales every column to sum to 1, turning counts into shares.
  const series = useMemo(
    () =>
      d3
        .stack<GenerationRow, Source>()
        .keys(data.sources)
        .value((row, key) => row[key])
        .offset(d3.stackOffsetExpand)(data.rows),
    [data]
  );

  // Dates parse as UTC midnight, so the axis must read them in UTC too.
  const x = useMemo(
    () =>
      d3
        .scaleUtc()
        .domain(d3.extent(data.rows, (d) => d.date) as [Date, Date])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const y = useMemo(
    () => d3.scaleLinear().domain([0, 1]).range([innerHeight, 0]),
    [innerHeight]
  );

  const color = useMemo(
    () => d3.scaleOrdinal<Source, string>().domain(data.sources).range(d3.schemeObservable10),
    [data]
  );

  // Linear interpolation only: a smoothing curve would overshoot the 0-1 band.
  const area = useMemo(
    () =>
      d3
        .area<d3.SeriesPoint<GenerationRow>>()
        .x((p) => x(p.data.date))
        .y0((p) => y(p[0]))
        .y1((p) => y(p[1])),
    [x, y]
  );

  const paths = useMemo(
    () => series.map((s) => ({ key: s.key, d: area(s) ?? '', fill: color(s.key) })),
    [series, area, color]
  );

  const xTicks: Tick[] = useMemo(
    () => x.ticks(6).map((v) => ({ value: d3.utcFormat('%Y')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(5).map((v) => ({ value: d3.format('.0%')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const legendColumnWidth = innerWidth / LEGEND_COLUMNS;

  return (
    <svg viewBox={`0 0 ${width} ${height}`} width="100%" height={height} role="img"
         aria-label="Normalized stacked area chart of the US electricity generation mix by source, 2001 to 2023">
      <g transform={`translate(${MARGIN.left},12)`}>
        {data.sources.map((source, i) => (
          <g
            key={source}
            transform={`translate(${(i % LEGEND_COLUMNS) * legendColumnWidth},${
              Math.floor(i / LEGEND_COLUMNS) * 16
            })`}
          >
            <rect width={9} height={9} y={-8} rx={2} fill={color(source)} />
            <text x={14} fontSize={11} fill="currentColor">
              {source}
            </text>
          </g>
        ))}
      </g>
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <text x={-MARGIN.left} y={-12} fontSize={11} fill="var(--muted)">
          Share of net generation
        </text>
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
        {paths.map((p) => (
          <path key={p.key} d={p.d} fill={p.fill} fillOpacity={0.9}>
            <title>{p.key}</title>
          </path>
        ))}
      </g>
    </svg>
  );
}
